$ErrorActionPreference = 'Stop'
$repoFull = 'fengie/mhw-mods'
$homeRoot = 'C:\Users\Xxkan'

function Invoke-Git {
    param([Parameter(ValueFromRemainingArguments=$true)][string[]]$Args)
    $out = & git @Args 2>&1
    $code = $LASTEXITCODE
    [pscustomobject]@{ Code=$code; Output=($out -join [Environment]::NewLine) }
}
function GitText {
    param([Parameter(ValueFromRemainingArguments=$true)][string[]]$Args)
    $r = Invoke-Git @Args
    if ($r.Code -ne 0) { throw "git $($Args -join ' ') failed ($($r.Code)): $($r.Output)" }
    return $r.Output.Trim()
}

$candidates = @(
    (Join-Path $homeRoot 'mhw-mods'),
    (Join-Path $homeRoot 'GitHub\mhw-mods'),
    (Join-Path $homeRoot 'Documents\GitHub\mhw-mods'),
    (Join-Path $homeRoot 'source\repos\mhw-mods'),
    (Join-Path $homeRoot 'Desktop\mhw-mods')
)
$repo = $null
foreach ($c in $candidates) {
    if (Test-Path (Join-Path $c '.git')) {
        Push-Location $c
        try {
            $url = GitText remote get-url origin
            if ($url -match 'fengie/mhw-mods') { $repo = $c; break }
        } finally { Pop-Location }
    }
}
if (-not $repo) {
    $found = Get-ChildItem -Path $homeRoot -Directory -Filter 'mhw-mods' -Recurse -ErrorAction SilentlyContinue |
        Where-Object { Test-Path (Join-Path $_.FullName '.git') } |
        Select-Object -First 20
    foreach ($d in $found) {
        Push-Location $d.FullName
        try {
            $url = GitText remote get-url origin
            if ($url -match 'fengie/mhw-mods') { $repo = $d.FullName; break }
        } catch {} finally { Pop-Location }
    }
}
if (-not $repo) { throw "Could not locate a local checkout of $repoFull under $homeRoot." }
Set-Location $repo

$r = Invoke-Git fetch origin --prune
if ($r.Code -ne 0) { throw "git fetch origin --prune failed: $($r.Output)" }
$baseline = GitText rev-parse origin/main

# Read governance from canonical remote main, not the potentially stale checked-out branch.
$gov = @(
 'AGENTS.md',
 'GLOBAL_GIT_DIRECTIVE.md',
 'NEXT-AGENT-START-HERE.md',
 '_AGENT_CONTEXT/CURRENT_REVISION.json',
 '_AGENT_CONTEXT/CONTINUITY_PROTOCOL.md',
 '_AGENT_CONTEXT/LEARNED_RULES.md',
 '_AGENT_CONTEXT/README_FIRST.md'
)
$missingGov = [System.Collections.Generic.List[string]]::new()
foreach ($f in $gov) {
    & git cat-file -e "origin/main:$f" 2>$null
    if ($LASTEXITCODE -ne 0) { $missingGov.Add($f); continue }
    [void](& git show "origin/main:$f")
}
if ($missingGov.Count -gt 0) { throw "Missing governance files on origin/main $baseline : $($missingGov -join ', ')" }

$worktreeBranches = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
$wt = & git worktree list --porcelain
foreach ($line in $wt) {
    if ($line -like 'branch refs/heads/*') {
        [void]$worktreeBranches.Add($line.Substring('branch refs/heads/'.Length))
    }
}

$currentBranch = GitText branch --show-current
$remoteShow = GitText remote show origin
$defaultRemote = (($remoteShow | Select-String 'HEAD branch:' | ForEach-Object { ($_ -split ':',2)[1].Trim() }) | Select-Object -First 1)
if (-not $defaultRemote) { $defaultRemote = 'main' }

$ghOk = $false
$openPrHeads = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
$prByHead = @{}
$protected = @{}
try {
    & gh auth status *> $null
    if ($LASTEXITCODE -eq 0) {
        $ghOk = $true
        $openJson = & gh pr list --repo $repoFull --state open --limit 200 --json number,title,headRefName,isDraft 2>$null
        if ($LASTEXITCODE -eq 0 -and $openJson) {
            foreach ($p in ($openJson | ConvertFrom-Json)) {
                if ($p.headRefName) {
                    [void]$openPrHeads.Add([string]$p.headRefName)
                    $prByHead[[string]$p.headRefName] = "open PR #$($p.number): $($p.title)"
                }
            }
        }
        $allJson = & gh pr list --repo $repoFull --state all --limit 200 --json number,title,headRefName,state,mergedAt 2>$null
        if ($LASTEXITCODE -eq 0 -and $allJson) {
            foreach ($p in ($allJson | ConvertFrom-Json)) {
                if ($p.headRefName -and -not $prByHead.ContainsKey([string]$p.headRefName)) {
                    $desc = "$($p.state) PR #$($p.number): $($p.title)"
                    if ($p.mergedAt) { $desc = "merged PR #$($p.number): $($p.title)" }
                    $prByHead[[string]$p.headRefName] = $desc
                }
            }
        }
        $branchesJson = & gh api --method GET "repos/$repoFull/branches?per_page=100" 2>$null
        if ($LASTEXITCODE -eq 0 -and $branchesJson) {
            foreach ($b in ($branchesJson | ConvertFrom-Json)) { $protected[[string]$b.name] = [bool]$b.protected }
        }
    }
} catch { $ghOk = $false }

function Get-RemoteBranches {
    @(& git for-each-ref --format='%(refname:strip=3)' refs/remotes/origin |
      Where-Object { $_ -and $_ -ne 'HEAD' -and $_ -ne 'main' } |
      Sort-Object -Unique)
}
function Get-LocalBranches {
    @(& git for-each-ref --format='%(refname:strip=2)' refs/heads |
      Where-Object { $_ -and $_ -ne 'main' } |
      Sort-Object -Unique)
}
function Test-PatchRepresented {
    param([string]$Ref)
    $out = & git cherry origin/main $Ref 2>$null
    if ($LASTEXITCODE -ne 0) { return $false }
    $lines = @($out | Where-Object { $_ -match '^[+-] ' })
    if ($lines.Count -eq 0) { return $true }
    return -not ($lines | Where-Object { $_ -like '+ *' })
}
function Classify-Ref {
    param([string]$Name,[string]$Ref,[bool]$IsRemote)
    $aheadText = & git rev-list --count "origin/main..$Ref" 2>$null
    if ($LASTEXITCODE -ne 0) {
        return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$null;Safe=$false;Reason='could not compute ahead count'}
    }
    $ahead = [int]$aheadText
    $isRelease = $Name -like 'release/*'
    $isDefault = $Name -eq $defaultRemote -or $Name -eq 'main'
    $isCurrent = (-not $IsRemote) -and ($Name -eq $currentBranch)
    $inWorktree = $worktreeBranches.Contains($Name)
    $isOpenPr = $openPrHeads.Contains($Name)
    $isProtected = $false
    if ($IsRemote -and $protected.ContainsKey($Name)) { $isProtected = [bool]$protected[$Name] }

    if ($isDefault) { return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$ahead;Safe=$false;Reason='default/main branch'} }
    if ($isCurrent) { return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$ahead;Safe=$false;Reason='currently checked out'} }
    if ($inWorktree) { return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$ahead;Safe=$false;Reason='checked out in a worktree'} }
    if ($isRelease) { return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$ahead;Safe=$false;Reason='release branch retained by policy'} }
    if ($Name -eq 'heaven-bridge') { return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$ahead;Safe=$false;Reason='Heaven Local Bridge infrastructure branch'} }
    if ($isProtected) { return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$ahead;Safe=$false;Reason='protected branch'} }
    if ($isOpenPr) { return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$ahead;Safe=$false;Reason=$prByHead[$Name]} }
    if (-not $ghOk) {
        return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$ahead;Safe=$false;Reason='gh unavailable; cannot prove protection/open-PR activity status'}
    }
    if ($ahead -eq 0) {
        return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$ahead;Safe=$true;Reason='all commits reachable from origin/main'}
    }
    if (Test-PatchRepresented $Ref) {
        $pr = if ($prByHead.ContainsKey($Name)) { "; $($prByHead[$Name])" } else { '' }
        return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$ahead;Safe=$true;Reason="all non-ancestor commits patch-equivalent on origin/main$pr"}
    }
    $pr2 = if ($prByHead.ContainsKey($Name)) { "; $($prByHead[$Name])" } else { '' }
    return [pscustomobject]@{Name=$Name;Ref=$Ref;Ahead=$ahead;Safe=$false;Reason="contains unique/non-equivalent commits$pr2"}
}

$r = Invoke-Git fetch origin --prune
if ($r.Code -ne 0) { throw "second git fetch origin --prune failed: $($r.Output)" }
$baseline = GitText rev-parse origin/main
$remoteBefore = Get-RemoteBranches
$localBefore = Get-LocalBranches
$remoteClass = @($remoteBefore | ForEach-Object { Classify-Ref $_ "origin/$_" $true })
$localClass = @($localBefore | ForEach-Object { Classify-Ref $_ $_ $false })

$r = Invoke-Git fetch origin --prune
if ($r.Code -ne 0) { throw "pre-delete git fetch origin --prune failed: $($r.Output)" }
$baseline2 = GitText rev-parse origin/main
if ($baseline2 -ne $baseline) {
    $baseline = $baseline2
    $remoteBefore = Get-RemoteBranches
    $localBefore = Get-LocalBranches
    $remoteClass = @($remoteBefore | ForEach-Object { Classify-Ref $_ "origin/$_" $true })
    $localClass = @($localBefore | ForEach-Object { Classify-Ref $_ $_ $false })
}

$deletedLocal = [System.Collections.Generic.List[string]]::new()
$deletedRemote = [System.Collections.Generic.List[string]]::new()
$deleteFailures = [System.Collections.Generic.List[string]]::new()

foreach ($c in $localClass | Where-Object Safe) {
    $re = Classify-Ref $c.Name $c.Name $false
    if (-not $re.Safe) { continue }
    $d = Invoke-Git branch -D -- $c.Name
    if ($d.Code -eq 0) { $deletedLocal.Add($c.Name) } else { $deleteFailures.Add("local $($c.Name): $($d.Output)") }
}
foreach ($c in $remoteClass | Where-Object Safe) {
    & git show-ref --verify --quiet "refs/remotes/origin/$($c.Name)"
    if ($LASTEXITCODE -ne 0) { continue }
    $re = Classify-Ref $c.Name "origin/$($c.Name)" $true
    if (-not $re.Safe) { continue }
    $d = Invoke-Git push origin --delete $c.Name
    if ($d.Code -eq 0) { $deletedRemote.Add($c.Name) } else { $deleteFailures.Add("remote $($c.Name): $($d.Output)") }
}

$prune = Invoke-Git fetch origin --prune
$pruneOk = $prune.Code -eq 0
$remoteAfter = Get-RemoteBranches
$localAfter = Get-LocalBranches
$remainingRemote = @($remoteAfter | ForEach-Object { Classify-Ref $_ "origin/$_" $true })

$preservedUniqueActive = @($remainingRemote | Where-Object {
    $_.Reason -match 'unique|open PR|release branch|protected|worktree|infrastructure|currently checked out|default/main'
} | ForEach-Object { "$($_.Name) :: ahead=$($_.Ahead) :: $($_.Reason)" })
$preservedUncertain = @($remainingRemote | Where-Object {
    $_.Reason -notmatch 'unique|open PR|release branch|protected|worktree|infrastructure|currently checked out|default/main'
} | ForEach-Object { "$($_.Name) :: ahead=$($_.Ahead) :: $($_.Reason)" })

$anomalies = [System.Collections.Generic.List[string]]::new()
foreach ($c in $remainingRemote) {
    if ($c.Ahead -eq 0 -and -not $c.Safe) {
        $anomalies.Add("$($c.Name) is fully contained in main but preserved because: $($c.Reason)")
    }
}
foreach ($f in $deleteFailures) { $anomalies.Add("DELETE FAILURE: $f") }
if (-not $ghOk) { $anomalies.Add('GitHub CLI authentication/status unavailable; no branches were considered deletion-safe.') }

$report = [ordered]@{
    repository = $repo
    origin_main_sha = $baseline
    default_branch = $defaultRemote
    current_branch = $currentBranch
    gh_available = $ghOk
    local_branch_count_before = $localBefore.Count + 1
    remote_branch_count_before = $remoteBefore.Count + 1
    branches_deleted_locally = @($deletedLocal)
    branches_deleted_remotely = @($deletedRemote)
    preserved_unique_active_release_protected = $preservedUniqueActive
    preserved_uncertain = $preservedUncertain
    stale_refs_pruned = $pruneOk
    prune_output = $prune.Output
    pr_branch_anomalies = @($anomalies)
    delete_failures = @($deleteFailures)
    final_local_branch_count = $localAfter.Count + 1
    final_remote_branch_count = $remoteAfter.Count + 1
    final_local_branches = @('main') + $localAfter
    final_remote_branches = @('main') + $remoteAfter
    no_known_unique_work_destroyed = ($deleteFailures.Count -eq 0)
}
$report | ConvertTo-Json -Depth 8
